// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 price，先计算右边的 12，再把结果作为它的初值。
    int price = 12;
    // 声明 count，先计算右边的 2，再把结果作为它的初值。
    int count = 2;
    // 声明 total，先计算右边的 price * count，再把结果作为它的初值。
    int total = price * count;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", total);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

