// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 x。这里没有给初值，必须先成功赋值，再读取它。
    double x;
    // 检查 scanf("%lf", &x)  不等于  1。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (scanf("%lf", &x) != 1)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 声明 y。这里没有给初值，必须先成功赋值，再读取它。
    double y;
    // 检查 x  小于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (x < 0)
        // 先计算右边 x * x，再把结果写入左边 y；左边原有的值会被覆盖。
        y = x * x;
    // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
    else
        // 先计算右边 x + 1，再把结果写入左边 y；左边原有的值会被覆盖。
        y = x + 1;
    // 按顺序用 %.2f 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%.2f\n", y);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

