// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 n，先计算右边的 5，再把结果作为它的初值。
    int n = 5;
    // 声明 product，先计算右边的 1，再把结果作为它的初值。
    unsigned long long product = 1;
    // 先做 int i = 1；每轮检查 i <= n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 1; i <= n; i++) {
        // 把 product 原有的值与 i 按 * 运算，再把结果写回 product。
        product *= i;
    }
    // 按顺序用 %llu 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%llu\n", product);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

