// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 op，先计算右边的 '+'，再把结果作为它的初值。
    char op = '+';
    // 这是同一类型的一组声明，逗号分开各个变量：a 初值为 7；b 初值为 2。
    int a = 7, b = 2;
    // 先算括号里的整数或字符值，再找相同常量的 case 作为入口；没有匹配项时从 default 进入。
    switch (op) {
    // 这是匹配入口。switch 括号里的值与 '+' 相同时，从冒号后开始执行。
    case '+':
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", a + b);
        // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
        break;
    // 这是匹配入口。switch 括号里的值与 '-' 相同时，从冒号后开始执行。
    case '-':
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", a - b);
        // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
        break;
    // 没有任何 case 与 switch 的值匹配时，执行这一支。
    default:
        // 把格式串和后面的值按顺序对应后显示出来。其中 \n 表示输出换行。
        printf("unknown\n");
    }
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

