        digits++;
        // 把 n 原有的值与 10 按 / 运算，再把结果写回 n。
        n /= 10;
    // 本轮已经执行完。现在检查 n != 0，为真再做一轮，为假退出。末尾的分号不能漏。
    } while (n != 0);
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", digits);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

