// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // first是本例的输出标记：1表示还没有输出第一项，0表示已经输出过。
    int first = 1;
    // 先做 int n = 2；每轮检查 n <= 7；为真才执行循环体。执行完一轮后做 n++，再检查条件。
    for (int n = 2; n <= 7; n++) {
        // 声明 prime，先计算右边的 1，再把结果作为它的初值。
        int prime = 1;
        // 先做 int d = 2；每轮检查 d <= n / d；为真才执行循环体。执行完一轮后做 d++，再检查条件。
        for (int d = 2; d <= n / d; d++) {
            // 检查 n % d  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (n % d == 0) {
                // 先计算右边 0，再把结果写入左边 prime；左边原有的值会被覆盖。
                prime = 0;
                // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
                break;
            }
        }
        // 检查 prime 等于 0，当前候选已经被判为合数。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (!prime) {
            // 这一轮余下的语句不再执行。for 先做更新项，再检查条件；while 则直接重新检查条件。
            continue;
