// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 count，先计算右边的 0，再把结果作为它的初值。
    int count = 0;
    // 先做 int n = 2；每轮检查 n <= 20；为真才执行循环体。执行完一轮后做 n++，再检查条件。
    for (int n = 2; n <= 20; n++) {
        // 声明 prime，先计算右边的 1，再把结果作为它的初值。
        int prime = 1;
        // 先做 int d = 2；每轮检查 d <= n / d；为真才执行循环体。执行完一轮后做 d++，再检查条件。
        for (int d = 2; d <= n / d; d++) {
            // 检查 n % d  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (n % d == 0) {
                // 先计算右边 0，再把结果写入左边 prime；左边原有的值会被覆盖。
                prime = 0;
                // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
                break;
            }
        }
        // 检查 prime 不是 0，即目前还没有找到因数。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (prime)
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            count++;
    }
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", count);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

