#include <stdio.h>

// 定义 draw 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
void draw(int n) {
    // 先检查 n > 0。为真就进入循环体，为假就直接去循环后面。
    while (n > 0) {
        // 把格式串和后面的值按顺序对应后显示出来。
        printf("*");
        // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
        n--;
    }
    // 把格式串和后面的值按顺序对应后显示出来。其中 \n 表示输出换行。
    printf("\n");
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
