    // 先做 int i = 0；每轮检查 i < n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 0; i < n; i++) {
        // 把 sum 原有的值与 a[i] 按 + 运算，再把结果写回 sum。
        sum += a[i];
        // 检查 a[i]  小于  minimum。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (a[i] < minimum)
            // 先计算右边 a[i]，再把结果写入左边 minimum；左边原有的值会被覆盖。
            minimum = a[i];
    }
    // 按顺序用 %.1f、%d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%.1f %d\n", (double)sum / n, minimum);
