// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 这是同一类型的一组声明，逗号分开各个变量：a[] 初值为 {5, 1, 4, 2, 3}；n 初值为 5。
    int a[] = {5, 1, 4, 2, 3}, n = 5;
    // 先做 int pass = 0；每轮检查 pass < n - 1；为真才执行循环体。执行完一轮后做 pass++，再检查条件。
    for (int pass = 0; pass < n - 1; pass++) {
        // 先做 int j = 0；每轮检查 j < n - 1 - pass；为真才执行循环体。执行完一轮后做 j++，再检查条件。
        for (int j = 0; j < n - 1 - pass; j++) {
            // 检查 a[j]  大于  a[j + 1]。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (a[j] > a[j + 1]) {
                // 声明 t，先计算右边的 a[j]，再把结果作为它的初值。
                int t = a[j];
                // 先计算右边 a[j + 1]，再把结果写入左边 a[j]；左边原有的值会被覆盖。
                a[j] = a[j + 1];
                // 先计算右边 t，再把结果写入左边 a[j + 1]；左边原有的值会被覆盖。
                a[j + 1] = t;
            }
        }
    }
    // 先做 int i = 0；每轮检查 i < n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 0; i < n; i++)
        // 按顺序用 %s、%d 显示对应参数，格式符要和参数类型匹配。
        printf("%s%d", i ? " " : "", a[i]);
    // 把格式串和后面的值按顺序对应后显示出来。其中 \n 表示输出换行。
    printf("\n");
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

