// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 text[32]，留出相应容量。这里没有初始化，读元素前要先成功赋值。
    char text[32];
    // 检查 !fgets(text, sizeof text, stdin)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!fgets(text, sizeof text, stdin))
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 先计算右边 '\0'，再把结果写入左边 text[strcspn(text, "\n")]；左边原有的值会被覆盖。
    text[strcspn(text, "\n")] = '\0';
    // 声明 len。计算正确终止字符串的有效字节数，不包含结束符。
    size_t len = strlen(text);
    // 声明 palindrome，先计算右边的 1，再把结果作为它的初值。
    int palindrome = 1;
    // 先做 size_t i = 0；每轮检查 i < len / 2；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (size_t i = 0; i < len / 2; i++) {
        // 检查 text[i]  不等于  text[len - 1 - i]。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (text[i] != text[len - 1 - i]) {
            // 先计算右边 0，再把结果写入左边 palindrome；左边原有的值会被覆盖。
            palindrome = 0;
            // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
            break;
        }
    }
    // 按顺序用 %zu、%s 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%zu %s\n", len, palindrome ? "yes" : "no");
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

