    line[strcspn(line, "\n")] = '\0';
    size_t len = strlen(line), digits = 0, spaces = 0;
    for (size_t i = 0; i < len; i++) {
        if (isdigit((unsigned char)line[i])) {
            digits++;
        }
        if (isspace((unsigned char)line[i])) {
            spaces++;
        }
    }
    printf("%zu %zu %zu %d\n", len, digits, spaces, strcmp(line, "A 7") == 0);
    return 0;
}

