// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 定义 swap 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
void swap(int *a, int *b) {
    // 声明 t，先计算右边的 *a，再把结果作为它的初值。
    int t = *a;
    // 先计算右边 *b，再把结果写入左边 *a；左边原有的值会被覆盖。
    *a = *b;
    // 先计算右边 t，再把结果写入左边 *b；左边原有的值会被覆盖。
    *b = t;
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 这是同一类型的一组声明，逗号分开各个变量：x 初值为 3；y 初值为 7。
    int x = 3, y = 7;
    // 调用 swap，把括号里的实参交给它；执行完后再回到下一条语句。
    swap(&x, &y);
    // 按顺序用 %d、%d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d %d\n", x, y);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

