// 先引入 <stddef.h>，让编译器认识大小及指针差值类型函数或常量的声明。
#include <stddef.h>

// 定义 sum 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
int sum(const int *a, int n) {
    // 声明 total，先计算右边的 0，再把结果作为它的初值。
    int total = 0;
    // 先做 int i = 0；每轮检查 i < n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 0; i < n; i++)
        // 把 total 原有的值与 a[i] 按 + 运算，再把结果写回 total。
        total += a[i];
    // 结束当前函数，把 total 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return total;
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 a[]，用 {2, 4, 6} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    int a[] = {2, 4, 6};
    // 按顺序用 %d、%td 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d %td\n", sum(a, 3), (a + 3) - a);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

