// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 n，先计算右边的 3，再把结果作为它的初值。
    int n = 3;
    // 声明 *a。按元素数和单项大小申请空间，保存返回地址；失败为NULL，成功时分配区字节置零。
    int *a = calloc((size_t)n, sizeof *a);
    // 检查 a 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!a)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 声明 sum，先计算右边的 0，再把结果作为它的初值。
    int sum = 0;
    // 先做 int i = 0；每轮检查 i < n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 0; i < n; i++) {
        // 先计算右边 (i + 1) * (i + 1)，再把结果写入左边 a[i]；左边原有的值会被覆盖。
        a[i] = (i + 1) * (i + 1);
        // 把 sum 原有的值与 a[i] 按 + 运算，再把结果写回 sum。
        sum += a[i];
    }
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", sum);
    // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
    free(a);
    // 先计算右边 NULL，再把结果写入左边 a；左边原有的值会被覆盖。
    a = NULL;
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

