// 定义 fact 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
unsigned long long fact(unsigned n) {
    // 检查 n  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (n == 0)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 结束当前函数，把 n * fact(n - 1) 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return n * fact(n - 1);
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 按顺序用 %llu 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%llu\n", fact(5));
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

