            // 结束当前函数，把 &a[i] 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
            return &a[i];
    // 结束当前函数，把 NULL 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return NULL;
}
