// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>

// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef struct Node {
    // 声明 value。这里没有给初值，必须先成功赋值，再读取它。
    int value;
    // 声明 *next。这里没有给初值，必须先成功赋值，再读取它。
    struct Node *next;
} Node;
// 定义 clear 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
void clear(Node *head) {
    // 先检查 head。为真就进入循环体，为假就直接去循环后面。
    while (head) {
        // 声明指针 *next，把 head->next 表示的地址保存进去；后续先确认目标有效再解引用。
        Node *next = head->next;
        // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
        free(head);
        // 先计算右边 next，再把结果写入左边 head；左边原有的值会被覆盖。
        head = next;
    }
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明指针 *head，把 NULL 表示的地址保存进去；后续先确认目标有效再解引用。
    Node *head = NULL;
    // 先做 int i = 1；每轮检查 i <= 3；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 1; i <= 3; i++) {
        // 声明 *node。按所需字节数申请空间，保存返回的地址；失败为NULL，成功后内容还未初始化。
        Node *node = malloc(sizeof *node);
        // 检查 node 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (!node) {
            // 调用 clear，把括号里的实参交给它；执行完后再回到下一条语句。
            clear(head);
            // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
            return 1;
        }
        // 先计算右边 i，再把结果写入左边 node->value；左边原有的值会被覆盖。
        node->value = i;
        // 先计算右边 head，再把结果写入左边 node->next；左边原有的值会被覆盖。
        node->next = head;
        // 先计算右边 node，再把结果写入左边 head；左边原有的值会被覆盖。
        head = node;
    }
    // first是本例的输出标记：1表示还没有输出第一项，0表示已经输出过。
    int first = 1;
    // 先做 Node *p = head；每轮检查 p；为真才执行循环体。执行完一轮后做 p = p->next，再检查条件。
    for (Node *p = head; p; p = p->next) {
