        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 把文件读写位置移回开头，并清除文件结束、错误标志；接下来可以从头读取。
    rewind(f);
    // 这是同一类型的一组声明，逗号分开各个变量：x 此处未赋初值；sum 初值为 0；count 初值为 0；result 此处未赋初值。
    int x, sum = 0, count = 0, result;
    // 先检查 (result = fscanf(f, "%d", &x)) == 1。为真就进入循环体，为假就直接去循环后面。
    while ((result = fscanf(f, "%d", &x)) == 1) {
        // 把 sum 原有的值与 x 按 + 运算，再把结果写回 sum。
        sum += x;
        // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
        count++;
    }
    // 检查 ferror(f) ，或者  result  不等于  EOF。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
