// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 定义 copy_name 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int copy_name(char *dst, size_t cap, const char *src) {
    // 声明 n。计算正确终止字符串的有效字节数，不包含结束符。
    size_t n = strlen(src);
    // 检查 n  大于或等于  cap。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (n >= cap)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
    memcpy(dst, src, n + 1);
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 name[4]，用 "" 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    char name[4] = "";
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", copy_name(name, sizeof name, "cat"));
    // 显示括号中的字符串，最后自动补一个换行。
    puts(name);
