#include <limits.h>

// 定义 add_checked 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int add_checked(int a, int b, int *out) {
    // 检查 (b  大于  0 ，并且  a  大于  INT_MAX - b) ，或者  (b  小于  0 ，并且  a  小于  INT_MIN - b)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b))
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先计算右边 a + b，再把结果写入左边 *out；左边原有的值会被覆盖。
    *out = a + b;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 out，先计算右边的 0，再把结果作为它的初值。
    int out = 0;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", add_checked(INT_MAX, 1, &out));
    // 检查 add_checked(20, 22, &out)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (add_checked(20, 22, &out))
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", out);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

