// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>
// 先引入 <errno.h>，让编译器认识库函数错误状态函数或常量的声明。
#include <errno.h>

// 定义 parse_port 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int parse_port(const char *s, int *out) {
    // 检查 !s[0]。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!s[0])
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先做 const char *p = s；每轮检查 *p；为真才执行循环体。执行完一轮后做 ++p，再检查条件。
    for (const char *p = s; *p; ++p)
        // 检查 *p  小于  '0' ，或者  *p  大于  '9'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (*p < '0' || *p > '9')
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
    // 先计算右边 0，再把结果写入左边 errno；左边原有的值会被覆盖。
    errno = 0;
    // 声明 *end。这里没有给初值，必须先成功赋值，再读取它。
    char *end;
    // 声明 value。把字符串解析成long，保存数值；还需检查结束位置、errno和允许范围。
    long value = strtol(s, &end, 10);
    // 检查 errno  等于  ERANGE ，或者  *end ，或者  value  小于  1 ，或者  value  大于  65535。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (errno == ERANGE || *end || value < 1 || value > 65535)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先计算右边 (int)value，再把结果写入左边 *out；左边原有的值会被覆盖。
    *out = (int)value;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 p，先计算右边的 0，再把结果作为它的初值。
    int p = 0;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", parse_port("8080abc", &p));
    // 检查 parse_port("8080", &p)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (parse_port("8080", &p))
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", p);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

