// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

static char *make_name(void) {
    // 声明 *p。按所需字节数申请空间，保存返回的地址；失败为NULL，成功后内容还未初始化。
    char *p = malloc(4);
    // 检查 p。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (p)
        // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
        memcpy(p, "cat", 4);
    // 结束当前函数，把 p 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return p;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明指针 *name，把 make_name() 表示的地址保存进去；后续先确认目标有效再解引用。
    char *name = make_name();
    // 检查 name 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!name)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 显示括号中的字符串，最后自动补一个换行。
    puts(name);
    // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
    free(name);
    // 先计算右边 NULL，再把结果写入左边 name；左边原有的值会被覆盖。
    name = NULL;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", name == NULL);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

