    char *p = malloc(4);
    // 检查 p。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (p)
        // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
        memcpy(p, "dog", 4);
    // 结束当前函数，把 p 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return p;
}

