#include <stdio.h>

// 定义 at 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int at(const int *a, size_t n, size_t i, int *out) {
    // 检查 i  大于或等于  n。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (i >= n)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先计算右边 a[i]，再把结果写入左边 *out；左边原有的值会被覆盖。
    *out = a[i];
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
