    // 这是同一类型的一组声明，逗号分开各个变量：a[] 初值为 {10, 20, 30}；value 初值为 0。
    int a[] = {10, 20, 30}, value = 0;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", at(a, 3, 3, &value));
    // 检查 at(a, 3, 2, &value)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (at(a, 3, 2, &value))
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", value);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

