// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 raw[]，用 {3, 0x41, 0, 0x42} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    unsigned char raw[] = {3, 0x41, 0, 0x42};
    // 声明 *f。创建临时二进制读写流，保存返回的文件指针；失败为NULL。
    FILE *f = tmpfile();
    // 检查 f 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!f)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 检查 fwrite(raw, 1, sizeof raw, f)  不等于  sizeof raw。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fwrite(raw, 1, sizeof raw, f) != sizeof raw) {
        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 把文件读写位置移回开头，并清除文件结束、错误标志；接下来可以从头读取。
    rewind(f);
    // 这是同一类型的一组声明，逗号分开各个变量：len 初值为 0；payload[8] 此处未赋初值。
    unsigned char len = 0, payload[8];
    // 检查 fread(&len, 1, 1, f)  不等于  1 ，或者  len  大于  sizeof payload ，或者  fread(payload, 1, len, f)  不等于  len。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fread(&len, 1, 1, f) != 1 || len > sizeof payload ||
        fread(payload, 1, len, f) != len) {
        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 先做 size_t i = 0；每轮检查 i < len；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (size_t i = 0; i < len; ++i)
        // 按顺序用 %02X、%s 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%02X%s", (unsigned)payload[i], i + 1 == len ? "\n" : " ");
    // 检查 fclose(f)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fclose(f) != 0)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

