// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 frame[8]，用 {0} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    unsigned char frame[8] = {0};
    // 这是同一类型的一组声明，逗号分开各个变量：first[] 初值为 {2, 'A'}；second[] 初值为 {'B'}。
    unsigned char first[] = {2, 'A'}, second[] = {'B'};
    // 声明 used，先计算右边的 0，再把结果作为它的初值。
    size_t used = 0;
    // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
    memcpy(frame + used, first, sizeof first);
    // 把 used 原有的值与 sizeof first 按 + 运算，再把结果写回 used。
    used += sizeof first;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", used >= 1u + frame[0]);
    // 检查 sizeof second  大于  sizeof frame - used。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (sizeof second > sizeof frame - used)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
    memcpy(frame + used, second, sizeof second);
    // 把 used 原有的值与 sizeof second 按 + 运算，再把结果写回 used。
    used += sizeof second;
    // 检查 frame[0]  大于  sizeof frame - 1。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (frame[0] > sizeof frame - 1)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", used >= 1u + frame[0]);
    // 检查 fwrite(frame + 1, 1, frame[0], stdout)  不等于  frame[0]。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fwrite(frame + 1, 1, frame[0], stdout) != frame[0])
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 只输出括号中指定的一个字符。putchar('\n') 输出的是换行。
    putchar('\n');
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

