// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef SOCKET socket_t;
// 在编译前定义这个名字；后面遇到它时按这里的文字替换，宏的参数和整体表达式都要保留括号。
#define BAD INVALID_SOCKET
// 在编译前定义这个名字；后面遇到它时按这里的文字替换，宏的参数和整体表达式都要保留括号。
#define shut_socket closesocket
// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef int addr_size;
// 上面的编译条件不满足时，保留这一支源码。
#else
// 先引入 <sys/socket.h>，让编译器认识对应接口函数或常量的声明。
#include <sys/socket.h>
// 先引入 <netinet/in.h>，让编译器认识对应接口函数或常量的声明。
#include <netinet/in.h>
// 先引入 <arpa/inet.h>，让编译器认识对应接口函数或常量的声明。
#include <arpa/inet.h>
// 先引入 <unistd.h>，让编译器认识对应接口函数或常量的声明。
#include <unistd.h>
// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef int socket_t;
// 在编译前定义这个名字；后面遇到它时按这里的文字替换，宏的参数和整体表达式都要保留括号。
#define BAD (-1)
// 在编译前定义这个名字；后面遇到它时按这里的文字替换，宏的参数和整体表达式都要保留括号。
#define shut_socket close
// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef socklen_t addr_size;
// 结束这一段条件编译范围，与上面的 #if、#ifdef 或 #ifndef 配对。
#endif
// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
// 编译前检查这个条件，只有条件满足时才保留下面这部分源码；它不是程序运行中的 if。
#ifdef _WIN32
    WSADATA ws;
    // 检查 WSAStartup(MAKEWORD(2, 2), &ws)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (WSAStartup(MAKEWORD(2, 2), &ws) != 0)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
// 结束这一段条件编译范围，与上面的 #if、#ifdef 或 #ifndef 配对。
#endif
    // 声明 result，先计算右边的 1，再把结果作为它的初值。
    int result = 1;
    // 这是同一类型的一组声明，逗号分开各个变量：server 初值为 BAD；client 初值为 BAD；peer 初值为 BAD。
    socket_t server = BAD, client = BAD, peer = BAD;
    // 声明 addr。这里没有给初值，必须先成功赋值，再读取它。
    struct sockaddr_in addr;
    // 调用 memset，把括号里的实参交给它；执行完后再回到下一条语句。
    memset(&addr, 0, sizeof addr);
    // 先计算右边 AF_INET，再把结果写入左边 addr.sin_family；左边原有的值会被覆盖。
    addr.sin_family = AF_INET;
    // 先计算右边 htonl(INADDR_LOOPBACK)，再把结果写入左边 addr.sin_addr.s_addr；左边原有的值会被覆盖。
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    // 先计算右边 htons(0)，再把结果写入左边 addr.sin_port；左边原有的值会被覆盖。
    addr.sin_port = htons(0);
    // 先计算右边 socket(AF_INET, SOCK_STREAM, 0)，再把结果写入左边 server；左边原有的值会被覆盖。
    server = socket(AF_INET, SOCK_STREAM, 0);
    // 检查 server  等于  BAD ，或者  bind(server, (struct sockaddr *)&addr, sizeof addr)  不等于  0 ，或者  listen(server, 1)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (server == BAD || bind(server, (struct sockaddr *)&addr, sizeof addr) != 0 ||
        listen(server, 1) != 0)
        // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
        goto done;
    // 声明 size，先计算右边的 sizeof addr，再把结果作为它的初值。
    addr_size size = sizeof addr;
    // 检查 getsockname(server, (struct sockaddr *)&addr, &size)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (getsockname(server, (struct sockaddr *)&addr, &size) != 0)
        // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
        goto done;
    // 先计算右边 socket(AF_INET, SOCK_STREAM, 0)，再把结果写入左边 client；左边原有的值会被覆盖。
    client = socket(AF_INET, SOCK_STREAM, 0);
    // 检查 client  等于  BAD ，或者  connect(client, (struct sockaddr *)&addr, sizeof addr)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (client == BAD || connect(client, (struct sockaddr *)&addr, sizeof addr) != 0)
        // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
        goto done;
    // 先计算右边 accept(server, NULL, NULL)，再把结果写入左边 peer；左边原有的值会被覆盖。
    peer = accept(server, NULL, NULL);
    // 检查 peer  等于  BAD。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (peer == BAD)
        // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
        goto done;
    // 声明数组 text[]，用 "hello" 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    const char text[] = "hello";
    // 这是同一类型的一组声明，逗号分开各个变量：sent 初值为 0；received 初值为 0；total 初值为 sizeof text - 1。
    size_t sent = 0, received = 0, total = sizeof text - 1;
    // 声明数组 buffer[16]，用 {0} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    char buffer[16] = {0};
    // 先检查 sent < total。为真就进入循环体，为假就直接去循环后面。
    while (sent < total) {
        // 声明 n，先计算右边的 (int)send(client, text + sent, (int)(total - sent), 0)，再把结果作为它的初值。
        int n = (int)send(client, text + sent, (int)(total - sent), 0);
        // 检查 n  小于或等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n <= 0)
            // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
            goto done;
        // 把 sent 原有的值与 (size_t)n 按 + 运算，再把结果写回 sent。
        sent += (size_t)n;
    }
    // 先检查 received < total。为真就进入循环体，为假就直接去循环后面。
    while (received < total) {
        // 声明 n，先计算右边的 (int)recv(peer, buffer + received, (int)(total - received), 0)，再把结果作为它的初值。
        int n = (int)recv(peer, buffer + received, (int)(total - received), 0);
        // 检查 n  小于或等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n <= 0)
            // 跳到 done 标号，集中执行资源清理。已经打开或申请的资源不能遗漏。
            goto done;
        // 把 received 原有的值与 (size_t)n 按 + 运算，再把结果写回 received。
        received += (size_t)n;
    }
    // 显示括号中的字符串，最后自动补一个换行。
    puts(buffer);
    // 先计算右边 0，再把结果写入左边 result；左边原有的值会被覆盖。
    result = 0;
// 这是 done 跳转标号，用于在同一函数内找到处理位置；标号本身不做计算。
done:
    // 检查 peer  不等于  BAD。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (peer != BAD)
        // 调用 shut_socket，把括号里的实参交给它；执行完后再回到下一条语句。
        shut_socket(peer);
    // 检查 client  不等于  BAD。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (client != BAD)
        // 调用 shut_socket，把括号里的实参交给它；执行完后再回到下一条语句。
        shut_socket(client);
    // 检查 server  不等于  BAD。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (server != BAD)
        // 调用 shut_socket，把括号里的实参交给它；执行完后再回到下一条语句。
        shut_socket(server);
// 编译前检查这个条件，只有条件满足时才保留下面这部分源码；它不是程序运行中的 if。
#ifdef _WIN32
    // 调用 WSACleanup，把括号里的实参交给它；执行完后再回到下一条语句。
    WSACleanup();
// 结束这一段条件编译范围，与上面的 #if、#ifdef 或 #ifndef 配对。
#endif
    // 结束当前函数，把 result 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return result;
}

