// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 定义 decode 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int decode(const unsigned char *p, size_t size, char *out, size_t cap) {
    // 检查 size  小于  1。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (size < 1)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 声明 len，先计算右边的 p[0]，再把结果作为它的初值。
    size_t len = p[0];
    // 检查 len  大于或等于  cap ，或者  len  不等于  size - 1。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (len >= cap || len != size - 1)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先做 size_t i = 0；每轮检查 i < len；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (size_t i = 0; i < len; ++i)
        // 检查 p[i + 1]  小于  32 ，或者  p[i + 1]  大于  126。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (p[i + 1] < 32 || p[i + 1] > 126)
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
    // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
    memcpy(out, p + 1, len);
    // 先计算右边 '\0'，再把结果写入左边 out[len]；左边原有的值会被覆盖。
    out[len] = '\0';
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 good[]，用 {2, 'O', 'K'} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    unsigned char good[] = {2, 'O', 'K'};
    // 声明数组 short_packet[]，用 {3, 'O', 'K'} 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    unsigned char short_packet[] = {3, 'O', 'K'};
    // 声明数组 text[8]，用 "" 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    char text[8] = "";
    // 检查 decode(good, sizeof good, text, sizeof text)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (decode(good, sizeof good, text, sizeof text))
        // 显示括号中的字符串，最后自动补一个换行。
        puts(text);
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", decode(short_packet, sizeof short_packet, text, sizeof text));
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

