// 定义 max_score 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int max_score(const int *a, size_t n, int *out) {
    // 检查 n  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (n == 0)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 声明 best，先计算右边的 a[0]，再把结果作为它的初值。
    int best = a[0];
    // 先做 size_t i = 1；每轮检查 i < n；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (size_t i = 1; i < n; ++i)
        // 检查 a[i]  大于  best。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (a[i] > best)
            // 先计算右边 a[i]，再把结果写入左边 best；左边原有的值会被覆盖。
            best = a[i];
    // 先计算右边 best，再把结果写入左边 *out；左边原有的值会被覆盖。
    *out = best;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

