#include <stdio.h>
// 先引入 <limits.h>，让编译器认识整数类型的边界函数或常量的声明。
#include <limits.h>

// 给一组状态取名字；没有另写数值时，第一项从 0 开始，后面逐项加 1。
enum Status { OK, ZERO_DIVISOR, OVERFLOW };
// 定义 divide 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static enum Status divide(int a, int b, int *out) {
    // 检查 b  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (b == 0)
        // 结束当前函数，把 ZERO_DIVISOR 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return ZERO_DIVISOR;
    // 检查 INT_MIN  小于  -INT_MAX ，并且  a  等于  INT_MIN ，并且  b  等于  -1。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (INT_MIN < -INT_MAX && a == INT_MIN && b == -1)
        // 结束当前函数，把 OVERFLOW 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return OVERFLOW;
    // 先计算右边 a / b，再把结果写入左边 *out；左边原有的值会被覆盖。
    *out = a / b;
    // 结束当前函数，把 OK 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return OK;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 result，先计算右边的 99，再把结果作为它的初值。
    int result = 99;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", divide(8, 0, &result));
    // 检查 divide(8, 2, &result)  等于  OK。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (divide(8, 2, &result) == OK)
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", result);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

