        // 检查 v->cap。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (v->cap) {
            // 检查 cap  大于  SIZE_MAX / 2。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (cap > SIZE_MAX / 2)
                // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
                return 0;
            // 把 cap 原有的值与 2 按 * 运算，再把结果写回 cap。
            cap *= 2;
        }
        // 检查 cap  大于  SIZE_MAX / sizeof *v->data。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (cap > SIZE_MAX / sizeof *v->data)
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
        // 声明 *next。先用临时指针接扩容结果，非空才可替换旧地址；失败时原对象仍在。
        int *next = realloc(v->data, cap * sizeof *v->data);
        // 检查 next 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (!next)
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
        // 先计算右边 next，再把结果写入左边 v->data；左边原有的值会被覆盖。
        v->data = next;
        // 先计算右边 cap，再把结果写入左边 v->cap；左边原有的值会被覆盖。
        v->cap = cap;
    }
    // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
    v->data[v->size++] = value;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 v，先计算右边的 {0}，再把结果作为它的初值。
    Vec v = {0};
    // 先做 int i = 1；每轮检查 i <= 5；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (int i = 1; i <= 5; ++i)
        // 检查 !push(&v, i)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (!push(&v, i)) {
            // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
            free(v.data);
            // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
            return 1;
        }
    // 按顺序用 %zu、%zu 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%zu %zu\n", v.size, v.cap);
    // 先做 size_t i = 0；每轮检查 i < v.size；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (size_t i = 0; i < v.size; ++i)
        // 按顺序用 %d、%s 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d%s", v.data[i], i + 1 == v.size ? "\n" : " ");
    // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
    free(v.data);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

