// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 定义 clamp 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int clamp(int x, int lo, int hi) {
    // 结束当前函数，把 x < lo ? lo : x > hi ? hi : x 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return x < lo ? lo : x > hi ? hi : x;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 定义一组放在一起的字段。每个成员分别保存一种相关信息，用成员名来区分。
    struct Case {
        // 这是同一类型的一组声明，逗号分开各个变量：in 此处未赋初值；expected 此处未赋初值。
        int in, expected;
    } cases[] = {{-1, 0}, {0, 0}, {5, 5}, {10, 10}, {11, 10}};
    // 声明 failed，先计算右边的 0，再把结果作为它的初值。
    int failed = 0;
    // 先做 size_t i = 0；每轮检查 i < sizeof cases / sizeof cases[0]；为真才执行循环体。执行完一轮后做 ++i，再检查条件。
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i)
        // 检查 clamp(cases[i].in, 0, 10)  不等于  cases[i].expected。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (clamp(cases[i].in, 0, 10) != cases[i].expected)
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            ++failed;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", failed);
    // 检查 failed。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (failed)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

