#include <stdio.h>

int main(void) {
    FILE *f = tmpfile();
    if (f == NULL) {
        fputs("cannot open\n", stderr);
        return 1;
    }
    if (fputs("A", f) == EOF || fputs("B\n", f) == EOF) {
        fclose(f);
        return 1;
    }
    rewind(f);
    int c;
    while ((c = fgetc(f)) != EOF) {
        putchar(c);
    }
    int ok = !ferror(f);
    if (fclose(f) != 0) {
        ok = 0;
    }
    return ok ? 0 : 1;
    return 0;
}

