// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>
// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>
// 先引入 <errno.h>，让编译器认识库函数错误状态函数或常量的声明。
#include <errno.h>

// 定义 parse_row 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int parse_row(const char *line, char *name, size_t cap, int *score) {
    // 声明 *comma。在字符串中查找字符，保存找到的位置地址，找不到得到NULL。
    const char *comma = strchr(line, ',');
    // 检查 !comma ，或者  comma  等于  line。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!comma || comma == line)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 声明 len，先计算右边的 (size_t)(comma - line)，再把结果作为它的初值。
    size_t len = (size_t)(comma - line);
    // 检查 len  大于或等于  cap。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (len >= cap)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 声明指针 *digits，把 comma + 1 表示的地址保存进去；后续先确认目标有效再解引用。
    const char *digits = comma + 1;
    // 检查 !*digits。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!*digits)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先做 const char *p = digits；每轮检查 *p；为真才执行循环体。执行完一轮后做 ++p，再检查条件。
    for (const char *p = digits; *p; ++p)
        // 检查 *p  小于  '0' ，或者  *p  大于  '9'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (*p < '0' || *p > '9')
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
    // 先计算右边 0，再把结果写入左边 errno；左边原有的值会被覆盖。
    errno = 0;
    // 声明 *end。这里没有给初值，必须先成功赋值，再读取它。
    char *end;
    // 声明 value。把字符串解析成long，保存数值；还需检查结束位置、errno和允许范围。
    long value = strtol(digits, &end, 10);
    // 检查 errno  等于  ERANGE ，或者  *end ，或者  value  大于  100。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (errno == ERANGE || *end || value > 100)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 按给定字节数复制数据；复制前必须确认源和目标范围有效，且两块范围不重叠。
    memcpy(name, line, len);
    // 先计算右边 '\0'，再把结果写入左边 name[len]；左边原有的值会被覆盖。
    name[len] = '\0';
    // 先计算右边 (int)value，再把结果写入左边 *score；左边原有的值会被覆盖。
    *score = (int)value;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 name[16]，用 "" 初始化。若花括号只列出部分初值，剩余元素按规则补零。
    char name[16] = "";
    // 声明 score，先计算右边的 0，再把结果作为它的初值。
    int score = 0;
    // 检查 parse_row("Alice,90", name, sizeof name, &score)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (parse_row("Alice,90", name, sizeof name, &score))
        // 按顺序用 %s、%d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%s %d\n", name, score);
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", parse_row("Bob,90x", name, sizeof name, &score));
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

