// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>
// 先引入 <stdint.h>，让编译器认识指定位宽的整数类型和大小边界函数或常量的声明。
#include <stdint.h>

// 定义 summarize 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
static int summarize(FILE *f, size_t *ok, size_t *error) {
    // 声明数组 line[64]，留出相应容量。这里没有初始化，读元素前要先成功赋值。
    char line[64];
    // 先计算右边 0，再把结果写入左边 *ok；左边原有的值会被覆盖。
    *ok = 0;
    // 先计算右边 0，再把结果写入左边 *error；左边原有的值会被覆盖。
    *error = 0;
    // 先检查 fgets(line, sizeof line, f)。为真就进入循环体，为假就直接去循环后面。
    while (fgets(line, sizeof line, f)) {
        // 声明 n。计算正确终止字符串的有效字节数，不包含结束符。
        size_t n = strlen(line);
        // 检查 n ，并且  line[n - 1]  等于  '\n'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n && line[n - 1] == '\n') {
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            line[--n] = '\0';
            // 检查 n ，并且  line[n - 1]  等于  '\r'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (n && line[n - 1] == '\r') {
                // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
                line[--n] = '\0';
            }
        // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
        } else if (!feof(f))
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;

        // 检查 strcmp(line, "OK")  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (strcmp(line, "OK") == 0) {
            // 检查 *ok  等于  SIZE_MAX。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (*ok == SIZE_MAX)
                // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
                return 0;
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            ++*ok;
        // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
        } else if (strcmp(line, "ERROR") == 0) {
            // 检查 *error  等于  SIZE_MAX。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (*error == SIZE_MAX)
                // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
                return 0;
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            ++*error;
        // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
        } else
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
    }
    // 结束当前函数，把 !ferror(f) 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return !ferror(f);
}

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 *f。创建临时二进制读写流，保存返回的文件指针；失败为NULL。
    FILE *f = tmpfile();
    // 检查 f 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!f)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 检查 fputs("OK\nERROR\nOK\n", f)  等于  EOF。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fputs("OK\nERROR\nOK\n", f) == EOF) {
        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 把文件读写位置移回开头，并清除文件结束、错误标志；接下来可以从头读取。
    rewind(f);
    // 这是同一类型的一组声明，逗号分开各个变量：ok 初值为 0；error 初值为 0。
    size_t ok = 0, error = 0;
    // 声明 good，先计算右边的 summarize(f, &ok, &error)，再把结果作为它的初值。
    int good = summarize(f, &ok, &error);
    // 检查 fclose(f)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fclose(f) != 0)
        // 先计算右边 0，再把结果写入左边 good；左边原有的值会被覆盖。
        good = 0;
    // 检查 !good。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!good)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 按顺序用 %zu、%zu 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("OK=%zu ERROR=%zu\n", ok, error);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

