    // 定义一组放在一起的字段。每个成员分别保存一种相关信息，用成员名来区分。
    struct Student a[] = {{"An", 70}, {"Bo", 90}, {"Ci", 80}};
    // 声明 sum，先计算右边的 0，再把结果作为它的初值。
    int sum = 0;
    // 先做 int i = 0；每轮检查 i < 3；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 0; i < 3; i++)
        // 把 sum 原有的值与 a[i].score 按 + 运算，再把结果写回 sum。
        sum += a[i].score;
    // 声明 average，先计算右边的 sum / 3.0，再把结果作为它的初值。
    double average = sum / 3.0;
    // 先做 int i = 0；每轮检查 i < 3；为真才执行循环体。执行完一轮后做 i++，再检查条件。
