        // 检查 a[i].score  大于  average。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (a[i].score > average)
            // 显示括号中的字符串，最后自动补一个换行。
            puts(a[i].name);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

