// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 定义 is_prime 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
int is_prime(int n) {
    // 检查 n  小于  2。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (n < 2)
        // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
        return 0;
    // 先做 int d = 2；每轮检查 d <= n / d；为真才执行循环体。执行完一轮后做 d++，再检查条件。
    for (int d = 2; d <= n / d; d++)
        // 检查 n % d  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n % d == 0)
            // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
            return 0;
    // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return 1;
}
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 count，先计算右边的 0，再把结果作为它的初值。
    int count = 0;
    // 先做 int n = 10；每轮检查 n <= 20；为真才执行循环体。执行完一轮后做 n++，再检查条件。
    for (int n = 10; n <= 20; n++)
        // 检查 is_prime(n)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (is_prime(n))
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            count++;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", count);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

