int main(void) {
    // 声明指针 *s，把 "abcba" 表示的地址保存进去；后续先确认目标有效再解引用。
    const char *s = "abcba";
    // 声明 n。计算正确终止字符串的有效字节数，不包含结束符。
    size_t n = strlen(s);
    // 声明 ok，先计算右边的 1，再把结果作为它的初值。
    int ok = 1;
    // 先做 size_t i = 0；每轮检查 i < n / 2；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (size_t i = 0; i < n / 2; i++)
        // 检查 s[i]  不等于  s[n - 1 - i]。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (s[i] != s[n - 1 - i]) {
            // 先计算右边 0，再把结果写入左边 ok；左边原有的值会被覆盖。
            ok = 0;
            // 立刻离开最近的一层循环或 switch，去执行它后面的语句；不会只退出 if。
            break;
        }
    // 显示括号中的字符串，最后自动补一个换行。
    puts(ok ? "yes" : "no");
