    return 0;
}

// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 给这个类型起一个别名；以后可用别名声明对象，别名本身不会创建变量。
typedef struct Node {
    // 声明 value。这里没有给初值，必须先成功赋值，再读取它。
    int value;
    // 声明 *next。这里没有给初值，必须先成功赋值，再读取它。
    struct Node *next;
} Node;
// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 这是同一类型的一组声明，逗号分开各个变量：c 初值为 {5, NULL}；b 初值为 {8, &c}；a 初值为 {2, &b}。
    Node c = {5, NULL}, b = {8, &c}, a = {2, &b};
    // 声明 count，先计算右边的 0，再把结果作为它的初值。
    int count = 0;
    // 先做 Node *p = &a；每轮检查 p；为真才执行循环体。执行完一轮后做 p = p->next，再检查条件。
    for (Node *p = &a; p; p = p->next)
        // 检查 p->value  大于  4。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (p->value > 4)
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            count++;
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", count);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 *f。打开指定路径与模式的文件，保存文件流指针；失败为NULL。
    FILE *f = fopen("study_even.txt", "w+");
    // 检查 f 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!f)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 检查 fprintf(f, "2 7 8 11\n")  小于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fprintf(f, "2 7 8 11\n") < 0) {
        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 把文件读写位置移回开头，并清除文件结束、错误标志；接下来可以从头读取。
    rewind(f);
    // 这是同一类型的一组声明，逗号分开各个变量：n 此处未赋初值；count 初值为 0；result 此处未赋初值。
    int n, count = 0, result;
    // 先检查 (result = fscanf(f, "%d", &n)) == 1。为真就进入循环体，为假就直接去循环后面。
    while ((result = fscanf(f, "%d", &n)) == 1)
        // 检查 n % 2  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n % 2 == 0)
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            count++;
    // 检查 ferror(f) ，或者  result  不等于  EOF。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (ferror(f) || result != EOF) {
        // 关闭前面打开的文件，结束对这个文件流的使用。完整版本还应核对关闭是否成功。
        fclose(f);
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%d\n", count);
    // 结束当前函数，把 fclose(f) == 0 ? 0 : 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return fclose(f) == 0 ? 0 : 1;
}
